    smallest = numbers[0]
    for number in numbers:
        if number < smallest:
            smallest = number

    # Find the largest number in the list
    largest = numbers[0]
    for number in numbers:
        if number > largest:
            largest = number

    # Create a new list with the smallest number as the first element and the largest number as the last element
    new_numbers = [smallest]
    for number in numbers[1:]:
        new_numbers.append(largest)

    return new_numbers

