def encode(message):
    vowels = 'aeiouAEIOU'
    result = []

    for char in message:
        if char.isalpha():
            if char in vowels:
                # Replace vowel with the next vowel in the sequence
                result.append(chr(ord(char) + 2))
            else:
                # Swap case of the letter
                result.append(char.swapcase())
        else:
            # Keep non-alphabetic characters unchanged
            result.append(char)

    return ''.join(result)

