    Example:
    >>> prod_signs([1, 2, 2, -4]) == -9
    >>> prod_signs([0, 1]) == 0
    >>> prod_signs([]) == None
    """

    if len(arr) == 0:
        return None
    else:
        sum = 0
        for i in arr:
            sum += abs(i)
        prod = 1
        for i in arr:
            if i > 0:
                prod *= 1
            elif i < 0:
                prod *= -1
            else:
                prod *= 0
        return sum * prod

