    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def is_valid(x, y):
        return 0 <= x < N and 0 <= y < N

    def bfs(start):
        queue = deque([(start, [grid[start[0]][start[1]]])])
        visited = set()
        visited.add(start)

        while queue:
            (x, y), path = queue.popleft()

            if len(path) == k:
                return path

            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if is_valid(nx, ny) and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append(((nx, ny), path + [grid[nx][ny]]))

        return None

    # Start BFS from each cell in the grid
    min_path = None
    for i in range(N):
        for j in range(N):
            path = bfs((i, j))
            if path is not None:
                if min_path is None or path < min_path:
                    min_path = path

    return min_path

